 *
 * Generated by sylius/starter-core: do not edit, add a contributor instead.
 */
final readonly class BrandContent
{
    public function __construct(
        public ?string $name = null,
        public ?string $logo = null,
        public ?string $logoAlt = null,
    ) {}

    /**
     * Returns a copy where the non-null values of $other replace the current ones.
     */
    public function merge(self $other): self
    {
        return new self(
            name: $other->name ?? $this->name,
            logo: $other->logo ?? $this->logo,
            logoAlt: $other->logoAlt ?? $this->logoAlt,
        );
    }
}
